fn mean(a: &[f64]) -> f64 {
    if a.is_empty() { return f64::NAN; }
    a.iter().sum::<f64>() / a.len() as f64
}

fn median(a: &[f64]) -> f64 {
    if a.is_empty() { return f64::NAN; }
    let mut v = a.to_vec();
    v.sort_by(|x,y| x.partial_cmp(y).unwrap());
    let n = v.len();
    if n % 2 == 1 { v[n/2] } else { (v[n/2-1] + v[n/2]) / 2.0 }
}

fn stdev(a: &[f64]) -> f64 {
    if a.len() < 2 { return f64::NAN; }
    let m = mean(a);
    let s: f64 = a.iter().map(|x| (x - m)*(x - m)).sum();
    (s / (a.len() as f64 - 1.0)).sqrt()
}

fn gcd(mut a: i64, mut b: i64) -> i64 {
