struct Fenwick { n: usize, bit: Vec<i64> }
impl Fenwick {
    fn new(n: usize) -> Self { Self { n, bit: vec![0; n+1] } }
    fn add(&mut self, mut idx: usize, delta: i64) {
        idx += 1; // 1-based
        while idx <= self.n {
            self.bit[idx] += delta;
            idx += idx & (!idx + 1); // idx += idx & -idx
        }
    }
    fn sum_prefix(&self, mut idx: usize) -> i64 {
        let mut res = 0i64; idx += 1;
        while idx > 0 {
            res += self.bit[idx];
            idx &= idx - 1;
        }
        res
    }
    fn range_sum(&self, l: usize, r: usize) -> i64 {
        if r < l { return 0 }
        self.sum_prefix(r) - if l==0 { 0 } else { self.sum_prefix(l-1) }
    }
}

