fn modbus_crc16_le(data: &[u8]) -> Vec<u8> {
    let mut crc: u16 = 0xFFFF;
    for &b in data {
        crc ^= b as u16;
        for _ in 0..8 {
            if (crc & 1) != 0 { crc = (crc >> 1) ^ 0xA001; } else { crc >>= 1; }
        }
    }
    vec![(crc & 0xFF) as u8, (crc >> 8) as u8]
}

fn crc32_ieee_be(data: &[u8]) -> Vec<u8> {
    const POLY: u32 = 0xEDB88320; // reflected poly for bitwise algo
    let mut crc: u32 = 0xFFFF_FFFF;
    for &b in data {
        let mut x = (crc ^ (b as u32)) & 0xFF;
        for _ in 0..8 {
            x = if (x & 1) != 0 { (x >> 1) ^ POLY } else { x >> 1 };
        }
        crc = (crc >> 8) ^ x;
    }
    crc ^= 0xFFFF_FFFF;
    crc.to_be_bytes().to_vec()
}

