fn quick_sort(v: &mut [i32]) {
    if v.len() <= 1 { return; }
    let p = v.len() / 2;
    let mut i = 0;
    for j in 0..v.len() {
        if v[j] < v[p] { v.swap(i, j); i += 1; }
    }
    v.swap(i, p);
    let (lo, hi) = v.split_at_mut(i);
    if !lo.is_empty() { quick_sort(lo); }
    if !hi.is_empty() { quick_sort(&mut hi[1..]); }
}

fn merge_sort(v: &[i32]) -> Vec<i32> {
    if v.len() <= 1 { return v.to_vec(); }
    let m = v.len() / 2;
    let l = merge_sort(&v[..m]);
    let r = merge_sort(&v[m..]);
    merge(&l, &r)
}
fn merge(l: &[i32], r: &[i32]) -> Vec<i32> {
    let mut res = Vec::with_capacity(l.len() + r.len());
    let mut i = 0; let mut j = 0;
    while i < l.len() && j < r.len() {
        if l[i] <= r[j] { res.push(l[i]); i += 1; } else { res.push(r[j]); j += 1; }
    }
    res.extend_from_slice(&l[i..]); res.extend_from_slice(&r[j..]);
    res
}

fn binary_search(v: &[i32], target: i32) -> Option<usize> {
    let mut l = 0; let mut r = v.len();
    while l < r {
        let m = (l + r) / 2;
        if v[m] == target { return Some(m); }
        else if v[m] < target { l = m + 1; } else { r = m; }
    }
    None
}

