impl<F: Fn(i32)->i32> FnDecorator for TimingDecorator<F> { fn call(&self, x: i32) -> i32 { let start = std::time::Instant::now(); let r = (self.inner)(x); println!("took {:?}", start.elapsed()); r } }

fn clamp(val: f64, min: f64, max: f64) -> f64 {
    val.max(min).min(max)
}

use base64::{Engine as _, engine::general_purpose};

fn base64_encode(data: &[u8]) -> String {
    general_purpose::STANDARD.encode(data)
}

fn base64_decode(encoded: &str) -> Result<Vec<u8>, base64::DecodeError> {
    general_purpose::STANDARD.decode(encoded)
}

fn str_reverse(s: &str) -> String {
    s.chars().rev().collect()
}

fn factorial(n: u64) -> u64 {
    (1..=n).product()
}

fn selection_sort(arr: &mut [i32]) {
    for i in 0..arr.len() - 1 {
        let min_idx = (i..arr.len()).min_by_key(|&j| arr[j]).unwrap();
        arr.swap(i, min_idx);
    }
}

fn insertion_sort(arr: &mut [i32]) {
    for i in 1..arr.len() {
        let key = arr[i];
        let mut j = i;
        while j > 0 && arr[j - 1] > key {
            arr[j] = arr[j - 1];
            j -= 1;
        }
        arr[j] = key;
    }
}

use std::collections::VecDeque;

struct Queue<T> {
    data: VecDeque<T>,
}

impl<T> Queue<T> {
    fn new() -> Self { Queue { data: VecDeque::new() } }
    fn enqueue(&mut self, item: T) { self.data.push_back(item); }
    fn dequeue(&mut self) -> Option<T> { self.data.pop_front() }
    fn peek(&self) -> Option<&T> { self.data.front() }
    fn len(&self) -> usize { self.data.len() }
    fn is_empty(&self) -> bool { self.data.is_empty() }
}
